import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class PropertyListBuilderTest {

    private PropertyListBuilder builder = new PropertyListBuilder();

    @Test
    public void addPropertyTest() {
        builder.add(new Property<>("DataSource", "mysql"));
        assertEquals(1, builder.getRootEntries().size());
    }

    @Test
    public void addDuplicatePropertyTest() {
        try {
            builder.add(new Property<>("DataSource", "mysql"));
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            // expected
        }
    }

    @Test
    public void createPropertiesTest() {
        List<Property<?>> result = new ArrayList<>();
        builder.add(new Property<>("DataSource", "mysql"));
        builder.add(new Property<>("security", "password"));
        assertEquals(2, builder.create().size());
    }

    @Test
    public void addRootPropertyTest() {
        Map<String, Object> map = new LinkedHashMap<>();
        builder.addRootProperty(map, "root");
        assertEquals(1, map.size());
    }

    private class Property implements Property<?> {
        String path;
        String name;

        public Property(String path) {
            this.path = path;
            this.name = path.split("\\.")[this.path.split("\\.").length - 1];
        }
    }

}

